  color: #111827;
}

/* (0,1,0) giá */
.gia {
  color: #16a34a;
  font-weight: bold;
}

/* (0,2,0) thẻ hết hàng: hai class thắng .the (0,1,0) */
.the.het-hang {
  background: #f3f4f6;
}

/* (0,2,0) giá trong thẻ hết hàng: thắng .gia (0,1,0) */
.het-hang .gia {
  color: #9ca3af;
  text-decoration: line-through;
}

